import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { HighlightDirective } from './highlight.directive';
import { TruncatePipe } from './truncate.pipe';

@NgModule({
  declarations: [HighlightDirective, TruncatePipe],
  imports: [CommonModule, FormsModule],
  exports: [
    CommonModule,
    FormsModule,
    HighlightDirective,
    TruncatePipe
  ]
})
export class SharedModule {}

slides.content:
Services provided in `AppModule` are singletons. But if you accidentally provide a service in a feature module, a new instance is created for that module’s injector.

**CoreModule** solves this:
* Provide all app‑wide services in `CoreModule`.
* Import `CoreModule` **only** in `AppModule`.
* Add a constructor guard to prevent accidental import elsewhere.

```typescript
constructor(@Optional() @SkipSelf() parentModule: CoreModule) {
  if (parentModule) {
    throw new Error('CoreModule is already loaded. Import it only in AppModule!');
  }
}
```

slides.codeSnippet:
@NgModule({
  declarations: [HeaderComponent, FooterComponent],
  imports: [CommonModule, RouterModule],
  exports: [HeaderComponent, FooterComponent],
  providers: [
    LoggerService,
    AuthService,
    UserService
  ]
})
export class CoreModule {
  constructor(@Optional() @SkipSelf() parentModule: CoreModule) {
    if (parentModule) {
      throw new Error('CoreModule is already loaded.');
    }
  }
}
